from typing import List


def card_range_part4(BIN: str, info: List[List[str]]) -> List[List[str]]:
    low, high = int(BIN + "0" * 10), int(BIN + "9" * 10)
    # 按 start 升序、end 降序排，外层区间总排在它包含的子区间前面
    ivs = sorted(([int(BIN + s), int(BIN + e), b] for s, e, b in info),
                 key=lambda x: (x[0], -x[1]))
    outer, inner = [], []
    for iv in ivs:
        if outer and iv[1] <= outer[-1][1]:
            inner.append(iv)          # Part 3：被包含的区间不参与补洞
        else:
            outer.append(iv)
    if outer:
        outer[0][0] = low                       # Part 1：补低端
        outer[-1][1] = high                     # Part 1：补高端
        for a, b in zip(outer, outer[1:]):      # Part 2：中间空洞交给左侧区间
            a[1] = b[0] - 1
    merged = []                                 # Part 4：相邻同品牌合并
    for iv in outer:
        if merged and merged[-1][2] == iv[2] and merged[-1][1] + 1 == iv[0]:
            merged[-1][1] = iv[1]
        else:
            merged.append(iv)
    res = sorted(merged + inner, key=lambda x: (x[0], -x[1]))
    return [[str(s).zfill(16), str(e).zfill(16), b] for s, e, b in res]
